// Shape of lib/demo/fixtures.json, generated by scripts/build-demo-fixtures.mjs from a
// real run of the verification pipeline on synthetic cohorts. Hand-written so JSON
// literals keep their unions; lib/demo/data.ts casts once.

export type Verdict = "meets_wzw" | "borderline" | "insufficient"
export type EconomicVerdict = "REIMBURSABLE" | "CONDITIONAL" | "REJECTED"
export type ReleaseAction = "released" | "returned"
export type ContractStatus = "monitoring" | "verifying" | "settled" | "returned"
export type PatientStatus = "completed" | "active" | "dropped_out" | "enrolled"
export type RuleId = "hba1c_reduction" | "cgm_time_in_range" | "weight_loss"

export interface Rule {
  id: RuleId
  label: string
  metric: "hba1cChange" | "tir" | "weightLossPct"
  operator: ">=" | "<=" | ">" | "<"
  target: number
  unit: string
  weight: number
}

export interface Template {
  id: string
  name: string
  episodeMonths: number
  plannedSessions: number
  eligibility: { metric: string; min: number; max: number }
}

export interface Release {
  cutoff: number
  borderline: number
  passPolicy: "all" | "any" | string
  pillarWeights: { wirksamkeit: number; zweckmaessigkeit: number; wirtschaftlichkeit: number }
  zweckmaessigkeit: { eligibleShareWeight: number; adherenceWeight: number }
}

export interface MonthlyPoint {
  month: number
  visitDate: string
  n: number
  active: number
  completed: number
  droppedOut: number
  meanHba1c: number
  meanHba1cChange: number
  meanTir: number
  meanWeightLossPct: number
  meanAdherencePct: number
  passing: { hba1c: number; tir: number; weight: number; all: number; any: number }
}

export interface PatientRow {
  id: string
  status: PatientStatus
  enrolled: string
  lastMeasured: string
  baselineHba1c: number
  latestHba1c: number
  hba1cChange: number
  tir: number
  baselineWeightKg: number
  latestWeightKg: number
  weightLossPct: number
  sessions: number
  sessionsTotal: number
  adherencePct: number
  complications: number
  benchmarkCostChf: number
  actualCostChf: number
  rulesPassed: boolean[]
  passed: boolean
  payoutChf: number
  achievement: number
}

export interface Scores {
  wirksamkeit: number
  zweckmaessigkeit: number
  wirtschaftlichkeit: number
  composite: number
  verdict: Verdict
}

export interface CohortSummary {
  total: number
  completed: number
  active: number
  droppedOut: number
  passed: number
  failed: number
  passRate: number
  avgHba1cChange: number
  avgTir: number
  avgWeightLossPct: number
  avgAdherencePct: number
  eligibleSharePct: number | null
  savingsChf: number
  savingsPct: number | null
}

export interface RulePerformance {
  ruleId: RuleId
  label: string
  passed: number
  failed: number
  passRate: number
}

export interface Economics {
  icerChfPerQaly: number
  icerNote: string | null
  qalyGain: number
  avertedCostNpvChf: number
  incrementalCostChf: number
  relativeRiskReduction: number
  verdict: EconomicVerdict
  efficiencyScore: number
  netBudgetImpactChf: number
  discountRate: number
  illustrative: string[]
}

export interface HorizonRow {
  years: number
  icerChfPerQaly: number
  icerNote: string | null
  qalyGain: number
  avertedCostNpvChf: number
  incrementalCostChf: number
  efficiencyScore: number
  verdict: EconomicVerdict
}

export interface Payout {
  type: string
  totalChf: number
  fixedBaseChf: number
  bonusEarnedChf: number
  bonusPoolChf: number
  bonusPoolUtilisationPct: number
}

export interface Settlement {
  action: ReleaseAction
  amountChf: number
  payeeAmountChf: number
  returnedToPayerChf: number
  auditHash: string
  reference: string
  sequence: number
  settledAt: string | null
}

export interface Integrity {
  auditHash: string
  events: number
  head: string | null
  reverify: {
    verdictMatches: boolean
    compositeMatches: boolean
    auditHashMatches: boolean
    chainValid: boolean
    recomputedHash: string
  } | null
}

export interface PaymentOrder {
  standard: string
  messageId: string
  endToEndId: string
  instructedAmountChf: number
  currency: string
  executionDate: string
  debtorName: string
  debtorIban: string
  creditorName: string
  creditorIban: string
}

export interface TimelineEvent {
  seq: number
  at: string
  actor: string
  kind: string
  text: string
  hash: string | null
  prevHash: string | null
}

export interface Contract {
  id: string
  name: string
  programme: string
  templateId: string
  payer: string
  provider: string
  source: "fhir" | "csv" | "synthetic"
  cohortSize: number
  committedChf: number
  perPatientChf: number
  baseShare: number
  cutoff: number
  horizonYears: number | null
  thresholdsVersion: string
  status: ContractStatus
  enrolledFrom: string
  asOf: string
  monthsElapsed?: number
  scores: Scores | null
  summary: CohortSummary
  rulePerformance: RulePerformance[]
  economics: Economics | null
  horizons: HorizonRow[] | null
  payout: Payout | null
  settlement: Settlement | null
  integrity: Integrity | null
  reconciliation: { ok: boolean; checks: number; failed: number } | null
  paymentOrder: PaymentOrder | null
  timeline: TimelineEvent[]
  transcript: string[] | null
}

export interface Walkthrough {
  passContractId: string
  failContractId: string
  commitment: {
    committedChf: number
    cohortSize: number
    perPatientChf: number
    baseShare: number
    cutoff: number
    episodeMonths: number
    payer: string
    provider: string
  }
}

export interface Fixtures {
  meta: { generatedAt: string; sourceRun: string; synthetic: true; thresholdsVersion: string; note: string }
  template: Template
  rules: Rule[]
  release: Release
  monthly: MonthlyPoint[]
  patients: PatientRow[]
  contracts: Contract[]
  walkthrough: Walkthrough
}
